(()=>{
 const E=Engineering,mv=()=>taggedVector('M','O','momentVector'),r=()=>taggedVector('r','OP','momentPosition'),momentSize=()=>symbolMarkup('|MO|','momentMagnitude','<mrow><mo>|</mo><msub><mi>M</mi><mi>O</mi></msub><mo>|</mo></mrow>'),mc=axis=>symbolMarkup('M'+axis,'moment_'+axis,'<msub><mi>M</mi><mi>'+axis+'</mi></msub>'),rc=axis=>symbolMarkup('r'+axis,'moment_r'+axis,'<msub><mi>r</mi><mi>'+axis+'</mi></msub>'),theta=()=>mi('θ','thetaMoment'),d=()=>mi('d','momentArm'),cross=()=>symbolMarkup('×','crossProduct','<mo>×</mo>');
 const entries={
  momentVector:['MO · moment about point O','The axial moment vector rOP × F, in N·m. It describes the force’s tendency to rotate the body about O. Its direction follows the right-hand rule. It is not a force vector or a displacement.'],
  momentPosition:['rOP · moment position vector','The displacement from the point O about which the moment is calculated to a point P on the force’s line of action: rOP = P − O, in metres. It must start at O. Using another point on that same line gives the same moment.'],
  momentMagnitude:['|MO| · moment magnitude','The nonnegative size of the moment vector, in N·m: √(Mx² + My² + Mz²). It also equals Fd, where d is the perpendicular distance to the force’s line of action. Magnitude alone does not specify rotational direction.'],
  momentArm:['d · perpendicular moment arm','The shortest distance from O to the infinite line of action of F, measured in metres. It is not generally the distance |rOP|. For a nonzero force, d = |rOP × F| / |F|. If the force line passes through O, d = 0. A zero force has no defined line-of-action direction.'],
  thetaMoment:['θ (theta) · angle between rOP and F','Here θ is the smaller angle, 0–180°, between the moment position vector rOP and the force F. It is not automatically an angle from the x axis. Moment magnitude is |rOP||F| sin θ. The angle is undefined if either vector is zero.'],
  momentSin:['sin · perpendicular moment factor','In |MO| = |rOP||F| sin θ, θ is between rOP and F. Sine selects the component perpendicular to rOP. At 0° or 180° the moment is zero; at 90° the moment magnitude is largest for fixed lengths.'],
  crossProduct:['× (cross) · vector product','r × F is a vector perpendicular to r and F, with magnitude |r||F| sin θ and right-hand-rule direction. Use the positive cycle i cross j = k, j cross k = i, k cross i = j. Reversing any pair gives the negative direction; a vector crossed with itself is zero. Order matters: F × r = −(r × F). This is different from the dot product, which gives a scalar.'],
  forceMoment:['F · applied force vector','The force applied at P, in N. Its components use the same Cartesian axes as rOP. For the moment about O, use rOP × F in this order. The force can be slid along its line of action on a rigid body without changing its moment about O.']
 };
 for(const axis of E.axes){entries['moment_'+axis]=[`M${axis} · signed moment about the ${axis} axis through O`, `The ${axis} component of the moment vector, in N·m. A positive value means the axial vector points along +${axis}, using the right-hand rule. For z in the xy plane, positive is counterclockwise when viewed from +z toward the plane; negative is clockwise.`];entries['moment_r'+axis]=[`r${axis} · moment position component`, `The ${axis} coordinate of P minus the ${axis} coordinate of O, measured in metres. It is part of the displacement from the moment reference point to the force line, not the perpendicular moment arm by itself.`];}
 E.symbols(entries,{
  momentCross:()=>mv()+mo('=')+r()+cross()+vector('F','forceMoment'),
  momentScalar:()=>mc('z')+mo('=')+rc('x')+sub('F','y')+mo('−')+rc('y')+sub('F','x'),
  momentArm:()=>momentSize()+mo('=')+mi('F')+d()+mo('=')+mo('|')+r()+mo('|')+mi('F')+mi('sin','momentSin')+theta()
 },[
  {title:'Calculate a moment with the cross product',body:'momentCross',use:'Find the <strong>moment vector about point O</strong> in 2D or 3D.',need:'The <strong>force components (N)</strong> and a <strong>displacement from O to a point on its line of action (m)</strong>.',condition:'Use <strong>r × F in that order</strong>, common axes, and consistent units. The result has <strong>N·m units</strong>. Reversing cross-product order reverses the answer.',example:'r = <strong>(2, 1, 0) m</strong> and F = <strong>(0, 100, 0) N</strong> give M = <strong>(0, 0, 200) N·m</strong>.',symbols:['momentVector','momentPosition','forceMoment','crossProduct']},
  {title:'Use signed scalar moments in the xy plane',body:'momentScalar',use:'Find the <strong>signed z moment</strong> from the contributions of Fx and Fy.',need:'The <strong>x and y components of rOP (m)</strong> and <strong>Fx, Fy (N)</strong>.',condition:'For a planar xy problem, the moment vector has only a z component. Use <strong>Mz = rx Fy − ry Fx</strong>: positive means counterclockwise when viewed from +z. The same formula is also the z component in 3D.',example:'r = <strong>(2, 1, 0) m</strong>, F = <strong>(50, 100, 0) N</strong>: Mz = <strong>2×100 − 1×50 = 150 N·m</strong>.',symbols:['moment_z','moment_rx','moment_ry','F_x','F_y']},
  {title:'Use a perpendicular moment arm',body:'momentArm',use:'Find <strong>moment magnitude</strong> from force magnitude and geometry.',need:'The <strong>force magnitude F (N)</strong> and <strong>perpendicular distance d (m)</strong>, or |rOP| and the angle θ between rOP and F.',condition:'Use the <strong>shortest distance to the force line</strong>, not automatically |rOP|. This is a magnitude equation; obtain the rotational direction from geometry or the right-hand rule.',example:'A <strong>100 N</strong> force with a <strong>2 m perpendicular arm</strong> gives a moment magnitude of <strong>200 N·m</strong>.',symbols:['momentMagnitude','F','momentArm','momentPosition','thetaMoment']}
 ]);
 let state={O:[0,0,0],P:[2,1,0],F:[0,100,0],view:'xy'};
 $('moment').innerHTML=`<div class="lesson-strip"><span class="number">04</span><div><h2>Where a force acts changes what it does.</h2><p>Choose the reference point. Build r. Calculate r × F.</p></div><button id="momentReset">Reset example</button></div><div class="lab-grid"><article class="panel"><div class="panel-heading"><h3>Moment about a point</h3><span class="live">● LIVE</span></div><p id="momentProblem" class="position-problem"></p><label>Diagram view<select id="momentView"><option value="xy">xy projection</option><option value="xz">xz projection</option><option value="yz">yz projection</option><option value="iso">3D projection</option></select></label><svg id="momentDiagram" viewBox="0 0 600 400" role="img" aria-label="Reference point, force application point, line of action and perpendicular moment arm"></svg><p class="projection-note"><strong>Diagram is relative to O.</strong> Position and moment-arm geometry share a metre scale. Force and moment-direction arrows have illustrative lengths; their directions are exact. Screen angles and projected lengths are not 3D measurements.</p><div class="coordinate-controls">${E.fields('momentO','Reference point O','m',state.O)}${E.fields('momentP','Application point P','m',state.P)}</div>${E.fields('momentF','Force components','N',state.F)}<div class="actions moment-actions"><button id="momentClockwise">Clockwise example</button><button id="momentThrough">Line through O</button><button id="moment3D">3D example</button><button id="momentSlide">Slide P along force line</button></div><p id="momentError" class="error" role="status"></p><div id="momentSummary" class="result-summary" aria-live="polite"></div><p id="momentRotation" class="projection-note"></p></article><article class="panel"><h3>Moment, step by step</h3><div class="symbol-help">Tap an <strong>underlined symbol</strong> for its meaning. Numerical products use full precision.</div><div id="momentSteps"></div></article></div><article class="panel concept"><h3>Three ways to check your moment.</h3><div class="concept-grid"><p><strong>Right-hand rule.</strong><br>Curl your fingers from r toward F through the smaller angle. Your thumb gives the moment direction. If the vectors are parallel, the cross product is zero.</p><p><strong>Perpendicular distance.</strong><br>Only the shortest distance from O to the force line belongs in Fd. Sliding P along that line changes r but preserves the moment.</p><p><strong>Cross-product order.</strong><br>Use <strong>r × F</strong>. Reversing to F × r reverses every component. The dot product measures projection and does not calculate a moment.</p></div></article><article class="panel">${Learning.crossReminder}</article><article id="momentPractice" class="panel position-practice"></article>`;
 function steps(s){
  const m=M.moment(s.O,s.P,s.F),pairs=[[1,2],[2,0],[0,1]],det='<mrow><mo>|</mo><mtable><mtr>'+['i','j','k'].map(label=>'<mtd>'+mi(label)+'</mtd>').join('')+'</mtr><mtr>'+E.axes.map(axis=>'<mtd>'+rc(axis)+'</mtd>').join('')+'</mtr><mtr>'+E.axes.map(axis=>'<mtd>'+sub('F',axis)+'</mtd>').join('')+'</mtr></mtable><mo>|</mo></mrow>';
  let output=E.row(1,'Build the moment position vector','Position from O to the force line',math(r()+mo('=')+E.text('P − O'))+E.axes.map((axis,i)=>math(rc(axis)+mo('=')+mo('(')+E.num(s.P[i])+mo(')')+mo('−')+mo('(')+E.num(s.O[i])+mo(')')+mo('=')+E.num(m.r[i])+E.text(' m'))).join('')+math(r()+mo('=')+E.vec(m.r,'m')),'<strong>Start at the reference point O.</strong> End at P, or any point on the force’s line of action. Coordinates must use the <strong>same origin and metre units</strong>.');
  output+=E.row(2,'Set up r × F','Cross product for moment about O',math(mv()+mo('=')+r()+cross()+vector('F','forceMoment'))+math(det),'<strong>Order matters.</strong> This determinant is a calculation aid in a <strong>right-handed Cartesian coordinate system</strong>. It produces an axial vector perpendicular to r and F.');
  output+=E.row(3,'Calculate each signed component','Scalar moment components',pairs.map(([a,b],i)=>math(mc(E.axes[i])+mo('=')+rc(E.axes[a])+sub('F',E.axes[b])+mo('−')+rc(E.axes[b])+sub('F',E.axes[a]))+math(mc(E.axes[i])+mo('=')+mo('(')+E.num(m.r[a])+mo(')')+mo('(')+E.num(s.F[b])+mo(')')+mo('−')+mo('(')+E.num(m.r[b])+mo(')')+mo('(')+E.num(s.F[a])+mo(')')+mo('=')+E.num(m.components[i])+E.text(' N·m'))).join('')+math(mv()+mo('=')+E.vec(m.components,'N·m')),'For the <strong>xy plane</strong>, only <strong>Mz = rx Fy − ry Fx</strong> remains. In 3D, retain <strong>all three signed components</strong>.');
  output+=E.row(4,'Find magnitude and perpendicular arm','Moment magnitude and perpendicular distance',math(momentSize()+mo('=')+'<msqrt><mrow>'+m.components.map((v,i)=>(i?mo('+'):'')+'<msup><mrow><mo>(</mo>'+E.num(v)+'<mo>)</mo></mrow><mn>2</mn></msup>').join('')+'</mrow></msqrt>'+mo('=')+E.num(m.magnitude)+E.text(' N·m'))+(m.arm===null?'Zero force: the moment is zero, but a force-line direction and perpendicular arm are undefined.':math(d()+mo('=')+fraction(momentSize(),mo('|')+vector('F','forceMoment')+mo('|'))+mo('=')+fraction(E.num(m.magnitude),E.num(m.forceLength))+mo('=')+E.num(m.arm)+E.text(' m'))),`<strong>|r| = ${E.round(m.rLength)} m</strong> is generally different from <strong>d</strong>. ${m.arm!==null?`Check: <strong>${E.round(m.forceLength)} N × ${E.round(m.arm)} m = ${E.round(m.magnitude)} N·m</strong>.`:''}`);
  output+=E.row(5,'Interpret direction and angle','Moment direction and angle between r and F',m.angle===null?'Angle undefined: r or F is zero.':math(theta()+mo('=')+'<msup><mi>cos</mi><mn>−1</mn></msup>'+mo('(')+fraction(r()+mo('·')+vector('F','forceMoment'),mo('|')+r()+mo('|')+mo('|')+vector('F','forceMoment')+mo('|'))+mo(')')+mo('=')+E.num(m.angle)+mo('°')),m.direction?`The moment’s unit direction is <strong>${E.tuple(m.direction)}</strong>. θ is <strong>between r and F</strong>; magnitude also equals |r||F| sin θ. Use the <strong>right-hand rule</strong> for rotational sense.`:'The moment is <strong>zero</strong>, so it has <strong>no defined direction</strong>.');
  output+=`<details class="direction-details"><summary>What if I reverse cross-product order?</summary><div class="step" data-equation="Reversed cross-product order"><div class="math">${math(vector('F','forceMoment')+cross()+r()+mo('=')+E.vec(m.components.map(v=>-v),'N·m'))}</div><p>This is <strong>the negative of the required moment</strong>. To calculate the force’s moment about O, use <strong>r × F</strong>.</p></div></details>`;return output;
 }
 function render(){
  const m=M.moment(state.O,state.P,state.F),length=Math.max(m.rLength,1),origin=[0,0,0],P=m.r,H=m.foot?m.foot.map((v,i)=>v-state.O[i]):null;
  $('momentProblem').innerHTML=`A force <strong>F = ${E.tuple(state.F)} N</strong> acts at <strong>P = ${E.tuple(state.P)} m</strong>. Find its moment about <strong>O = ${E.tuple(state.O)} m</strong>.`;$('momentSteps').innerHTML=steps(state);$('momentError').textContent='';$('momentSummary').innerHTML=`<div><small>MOMENT MAGNITUDE</small>${E.round(m.magnitude)} N·m</div><div><small>PERPENDICULAR ARM</small>${m.arm===null?'Undefined':E.round(m.arm)+' m'}</div>`;
  $('momentRotation').textContent=m.magnitude<1e-10?'Zero moment: the force is zero or its line of action passes through O.':m.components[0]===0&&m.components[1]===0?`Mz = ${E.round(m.components[2])} N·m: ${m.components[2]>0?'counterclockwise (+z)':'clockwise (−z)'} when viewed from +z toward the xy plane.`:'The 3D moment direction follows the right-hand rule; inspect its signed Cartesian components.';
  const items=[{start:origin,end:P,color:'#8cbcff',label:'rOP',pointEnd:'P',arrow:true}];
  if(m.forceUnit){items.push({start:P.map((v,i)=>v-m.forceUnit[i]*length),end:P.map((v,i)=>v+m.forceUnit[i]*length),color:'#617384',label:'force line',dashed:true},{start:origin,end:H,color:'#efbd77',label:'d / foot H',dashed:true},{start:P,end:P.map((v,i)=>v+m.forceUnit[i]*length*.6),color:'#b4f178',label:'F (direction)',arrow:true});}
  if(m.direction)items.push({start:origin,end:m.direction.map(v=>v*length*.6),color:'#d3a0ee',label:'MO (direction)',arrow:true});E.diagram('momentDiagram',state.view,items,[{origin:[0,0,0],first:m.r,second:state.F,label:'θ: r to F'}]);
 }
 function sync(){E.sync('momentO',state.O);E.sync('momentP',state.P);E.sync('momentF',state.F);$('momentView').value=state.view;}
 for(const id of ['momentO','momentP','momentF'])E.axes.forEach((_,i)=>$(id+i).addEventListener('input',()=>{try{[state.O,state.P,state.F]=E.read(['momentO','momentP','momentF']);render();}catch(e){$('momentError').textContent=e.message;}}));
 $('momentView').onchange=()=>{state.view=$('momentView').value;render();};$('momentReset').onclick=()=>{state={O:[0,0,0],P:[2,1,0],F:[0,100,0],view:'xy'};sync();render();};$('momentClockwise').onclick=()=>{state={O:[0,0,0],P:[2,1,0],F:[0,-100,0],view:'xy'};sync();render();};$('momentThrough').onclick=()=>{state={O:[0,0,0],P:[2,1,0],F:[200,100,0],view:'xy'};sync();render();};$('moment3D').onclick=()=>{state={O:[1,1,1],P:[3,4,5],F:[100,-50,200],view:'iso'};sync();render();};$('momentSlide').onclick=()=>{const m=M.moment(state.O,state.P,state.F);if(!m.forceUnit){$('momentError').textContent='A zero force has no defined force line along which to slide P.';return;}const next=state.P.map((v,i)=>v+m.forceUnit[i]*2);if(next.some(v=>Math.abs(v)>10000)){$('momentError').textContent='Sliding would exceed the coordinate input bounds.';return;}state.P=next;sync();render();};
 const cases=[{name:'Counterclockwise planar moment',O:[0,0,0],P:[2,1,0],F:[50,100,0]},{name:'Clockwise planar moment',O:[0,0,0],P:[2,1,0],F:[0,-100,0]},{name:'Force line through O',O:[0,0,0],P:[2,1,0],F:[200,100,0]},{name:'3D moment, shifted reference point',O:[1,1,1],P:[3,4,5],F:[100,-50,200]}].map(c=>({...c,problem:`For <strong>O = ${E.tuple(c.O)} m</strong>, <strong>P = ${E.tuple(c.P)} m</strong>, and <strong>F = ${E.tuple(c.F)} N</strong>, find the <strong>signed moment components</strong> and <strong>moment magnitude</strong>.`,feedback:'Check r = P − O and use r × F. In the xy plane, Mz = rx Fy − ry Fx. Moment magnitude is nonnegative. Answers within 0.1 N·m are accepted.'}));
 E.practice({id:'momentPractice',title:'Calculate the moment about O.',cases,targets:c=>{const m=M.moment(c.O,c.P,c.F);return [...m.components.map((v,i)=>({label:`M${E.axes[i]} (N·m)`,value:v,tolerance:.1})),{label:'|MO| (N·m)',value:m.magnitude,tolerance:.1}];},solution:steps,hints:['Start by subtracting O from P. The force application point’s coordinates alone work only if O is the coordinate origin.','Use Mx = ry Fz − rz Fy; My = rz Fx − rx Fz; Mz = rx Fy − ry Fx.','Keep component signs. Use √(Mx² + My² + Mz²) only after finding the vector components.']});render();
})();
